-- 1. Tables in public with row-level security OFF. Expected: no rows. select c.relname as table_without_rls from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relkind = 'r' and not c.relrowsecurity;  -- 2. Tables that point at auth.users but do NOT delete with the user. Expected: no rows. -- A row here can make "Delete my account" fail or leave data behind. select conrelid::regclass as table_name, conname, confdeltype as on_delete from pg_constraint where contype = 'f' and confrelid = 'auth.users'::regclass and confdeltype <> 'c';  -- 3. Foreign keys inside public that block a cascading delete (restrict). Expected: no rows. select conrelid::regclass as table_name, conname, confrelid::regclass as points_at from pg_constraint where contype = 'f' and connamespace = 'public'::regnamespace and confdeltype = 'r';
